def remove_Occ(string, char):  
    start = 0  
    end = len(string) - 1  
    while start <= end:  
        if string[start] == char:  
            string = string[:start] + string[start+1:]  
            end -= 1  
        elif string[end] == char:  
            string = string[:end] + string[end+1:]  
            start += 1  
        else:  
