def rearange_string(s):
    # Create dictionary to count each letter
    letter_count = {}
    for letter in s:
        if letter in letter_count:
            letter_count[letter] += 1
        else:
            letter_count[letter] = 1

    # Create list of letters, count
    letter_list = []
    for letter, count in letter_count.items():
        letter_list.append((letter, count))

    # Sort list by count, then by letter
    letter_list.sort(key=lambda x: (x[1], x[0]))

    # Create new string, add letters to it
    new_string = ""
    for letter, count in letter_list:
        new_string += letter * count

    # Check if new string has two same letters next to each other
    for i in range(len(new_string) - 1):
        if new_string[i] == new_string[i + 1]:
            return False

    return new_string

