def max_sum_increasing_subseq(arr, n, i, k):  
    # Initialize dp array.  
    dp = [0] * n  
    dp[i] = arr[i]  
    # Iterate through array.  
    for j in range(i + 1, n):  
        # If jth element greater than ith element, update dp[j] with maximum of dp[j] and dp[i] + arr[j].  
        if arr[j] > arr[i]:  
            dp[j] = max(dp[j], dp[i] + arr[j])  
        # If jth element equal to ith element, update dp[j] with maximum of dp[j] and arr[j].  
        elif arr[j] == arr[i]:  
            dp[j] = max(dp[j], arr[j])  
    # Return maximum value in dp array.  
    return max(dp)

