        elif bracket == "]":  
            close_bracket += 1  
    if open_bracket != close_bracket:  
        return -1  
    else:  
        swap_count = 0  
        for bracket in bracket_string:  
            if bracket == "[":  
                open_bracket -= 1  
            elif bracket == "]":  
