def sum_of_digits(numbers):  
    sum = 0  
    for number in numbers:  
        if type(number) == int:  
            while number > 0:  
                sum += number % 10  
                number //= 10  
        elif type(number) == str:  
            for char in number:  
                if char.isdigit():  
                    sum += int(char)  
    return sum

